//go:build ignore

// Copy into upstream converter/internal/ooxml and run TestCodexOOXMLPackage.
package ooxml
import("archive/zip";"bytes";"encoding/json";"fmt";"math/rand";"os";"path/filepath";"sort";"testing")
func TestCodexOOXMLPackage(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};samples:=[][]byte{};for _,name:=range []string{"basic.xlsx","features.xlsx","math.xlsx","print.xlsx"}{b,e:=os.ReadFile(filepath.Join("../../xlsx/testdata",name));if e!=nil{t.Fatal(e)};samples=append(samples,b)};r:=rand.New(rand.NewSource(42851));rels:=[]string{`<Relationships><Relationship Id="rId1" Type="x/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId10" Type="x/theme" Target="../theme.xml"/><Relationship Id="rId2" Type="x/theme" Target="/theme.xml"/></Relationships>`,`<Relationships><Relationship Id="1" Type="x/link" Target="https://example.test/x" TargetMode="External"/><Relationship Id="2" Type="x/link" Target="../a/./b/../c"/></Relationships>`,`<Relationships><Relationship Id="rId1" Target="a"/><Relationship Id="rId1" Target="b"/></Relationships>`,`<Relationships><Relationship Id="x" Type="a" Target="file.xml"/></Relationships>`,`<Relationships><Relationship`, `<Relationships/>`};names:=[]string{"xl/workbook.xml","XL/WORKBOOK.XML","/xl/workbook.xml","xl\\workbook.xml","xl/worksheets/sheet1.xml","hello.txt","_rels/.rels","xl/_rels/workbook.xml.rels"};for i:=0;i<800;i++{var b bytes.Buffer;w:=zip.NewWriter(&b);for j:=0;j<1+r.Intn(8);j++{name:=names[r.Intn(len(names))];f,e:=w.CreateHeader(&zip.FileHeader{Name:name,Method:uint16(8*r.Intn(2))});if e!=nil{t.Fatal(e)};content:=fmt.Sprintf("text%d",r.Intn(100));if name=="_rels/.rels"||name=="xl/_rels/workbook.xml.rels"{content=rels[r.Intn(len(rels))]};f.Write([]byte(content))};if e:=w.Close();e!=nil{t.Fatal(e)};samples=append(samples,append([]byte{},b.Bytes()...))};queries:=[]string{"xl/workbook.xml","/XL/WORKBOOK.XML","xl\\workbook.xml","xl/worksheets/sheet1.xml","hello.txt","_rels/.rels","missing"};out:=[]any{};for _,data:=range samples {p,e:=Open(bytes.NewReader(data),int64(len(data)));if e!=nil{t.Fatal(e)};files:=[]any{};for _,name:=range queries{size,ok:=p.PartSize(name);var content any=nil;var errmsg string;if ok{v,e:=p.Read(name);if e!=nil{errmsg=e.Error()}else{content=v}};files=append(files,[]any{p.Has(name),size,content,errmsg})};all:=[]any{};best:=[]any{};for _,src:=range []string{"","xl/workbook.xml","/xl/workbook.xml"}{m:=p.Rels(src);keys:=make([]string,0,len(m));for k:=range m{keys=append(keys,k)};sort.Strings(keys);items:=[]any{};for _,k:=range keys{v:=m[k];items=append(items,[]any{v.ID,v.Type,v.Target,v.External})};all=append(all,items);selected,ok:=p.RelOfType(src,"/theme");if ok{best=append(best,[]any{selected.ID,selected.Type,selected.Target,selected.External})}else{best=append(best,nil)}};detect:=bytes.HasPrefix(data,[]byte("PK\x03\x04"))&&p.Has("xl/workbook.xml");out=append(out,map[string]any{"input":data,"queries":queries,"want":[]any{files,all,best,detect}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/ooxml/package.json"),b,0644);e!=nil{t.Fatal(e)}}
